@settings(max_examples=50, deadline=None)
def test_prop_valid_constructor_parameters_are_accepted(max_loans, max_renewals, period):
    """A Service must be constructible with non-negative integer limits and a positive loan_period, and use them for due_at."""
    c = FakeClock(10.0)
    s = Service(c, max_loans=max_loans, max_renewals=max_renewals, loan_period=period)
